import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Truck, 
  FileText, 
  LogOut, 
  Bot,
  Activity,
  ScanLine,
  Box,
  ShieldCheck,
  Building2,
  Menu,
  X,
  Wallet,
  Settings,
  Wine,
  Stamp
} from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';

interface LayoutProps {
  children: React.ReactNode;
  user: User;
  onLogout: () => void;
}

const NavItem = ({ to, icon: Icon, label, active, onClick }: { to: string; icon: any; label: string; active: boolean; onClick?: () => void }) => (
  <Link
    to={to}
    onClick={onClick}
    className={`flex items-center space-x-3 px-4 py-3 rounded-lg transition-all duration-200 ${
      active 
        ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/20' 
        : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    <Icon size={20} className={`shrink-0 ${active ? 'animate-pulse' : ''}`} />
    <span className="font-medium">{label}</span>
  </Link>
);

const Layout: React.FC<LayoutProps> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Close menu when route changes (fallback)
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location.pathname]);

  const handleNavClick = () => {
    setIsMobileMenuOpen(false);
  };

  // Role Checks
  const isAuthority = user.role === UserRole.REGULATOR || user.role === UserRole.AUDITOR;
  const isManufacturer = user.role === UserRole.MANUFACTURER;
  const isDistributor = user.role === UserRole.DISTRIBUTOR;

  return (
    <div className="flex h-[100dvh] bg-slate-50 overflow-hidden">

      {/* Mobile Backdrop */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/80 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      {/* Sidebar Navigation */}
      <div className={`
        fixed inset-y-0 left-0 z-50 w-72 bg-slate-900 text-white flex flex-col shadow-2xl transition-transform duration-300 ease-out border-r border-slate-800
        lg:translate-x-0 lg:static lg:inset-auto
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 flex items-center justify-between border-b border-slate-800/50 bg-slate-900">
          <div className="flex items-center space-x-3">
            <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 p-2.5 rounded-xl shadow-lg shadow-indigo-500/20">
              <Stamp size={24} className="text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">E-Ledger</h1>
              <p className="text-[10px] font-medium text-indigo-400 uppercase tracking-wider">GS1 Supply Chain Network</p>
            </div>
          </div>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="lg:hidden text-slate-400 hover:text-white p-1 rounded-md hover:bg-slate-800 transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        <nav className="flex-1 px-4 py-6 space-y-1.5 overflow-y-auto custom-scrollbar">
          <NavItem to="/dashboard" icon={LayoutDashboard} label="Control Dashboard" active={location.pathname === '/dashboard'} onClick={handleNavClick} />
          <NavItem to="/batches" icon={Wine} label="Product Inventory" active={location.pathname === '/batches'} onClick={handleNavClick} />

          {!isAuthority && (
            <NavItem to="/transfers" icon={Truck} label="Logistics & Permits" active={location.pathname === '/transfers'} onClick={handleNavClick} />
          )}

          <NavItem to="/financials" icon={Wallet} label="Duty & Tax Logs" active={location.pathname === '/financials'} onClick={handleNavClick} />

          {!isAuthority && (
            <NavItem to="/vrs" icon={ShieldCheck} label="Returns / Seizures" active={location.pathname === '/vrs'} onClick={handleNavClick} />
          )}

          {(isManufacturer || isDistributor) && (
            <NavItem to="/sscc" icon={Box} label="Palletization" active={location.pathname === '/sscc'} onClick={handleNavClick} />
          )}

          <NavItem to="/network" icon={Building2} label="Network Directory" active={location.pathname === '/network'} onClick={handleNavClick} />

          {isAuthority && (
            <NavItem to="/reports" icon={FileText} label="Compliance Reports" active={location.pathname === '/reports'} onClick={handleNavClick} />
          )}

          <NavItem to="/verify" icon={ScanLine} label="Verify Authenticity" active={location.pathname === '/verify'} onClick={handleNavClick} />
          <NavItem to="/assistant" icon={Bot} label="Audit Assistant" active={location.pathname === '/assistant'} onClick={handleNavClick} />
        </nav>

        <div className="p-4 border-t border-slate-800 bg-slate-900/50">
          <Link to="/settings" className="block group mb-2" onClick={handleNavClick}>
             <div className="flex items-center space-x-3 px-4 py-2 text-slate-400 hover:text-white transition-colors">
               <Settings size={18} />
               <span className="text-sm font-medium">System Config</span>
             </div>
          </Link>

          <Link to="/profile" className="block group" onClick={handleNavClick}>
            <div className="flex items-center space-x-3 px-4 py-3 mb-2 bg-slate-800 rounded-xl border border-slate-700 group-hover:bg-slate-700/80 transition-all">
              <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center font-bold text-white shrink-0 shadow-md">
                {user.name.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="text-sm font-semibold truncate text-white group-hover:text-indigo-200 transition-colors">{user.name}</p>
                <p className="text-[10px] text-slate-400 truncate uppercase tracking-wide">
                  {user.role === 'MANUFACTURER' ? 'Manufacturer' : 
                   user.role === 'REGULATOR' ? 'Regulatory Officer' : 
                   user.role === 'DISTRIBUTOR' ? 'Warehouse Hub' : user.role}
                </p>
              </div>
            </div>
          </Link>
          <button 
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2 text-slate-400 hover:text-red-400 hover:bg-red-950/30 rounded-lg transition-colors"
          >
            <LogOut size={18} />
            <span className="text-sm font-medium">Secure Sign Out</span>
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col overflow-hidden w-full relative bg-slate-50">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-8 shadow-sm shrink-0 z-10">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsMobileMenuOpen(true)}
              className="lg:hidden p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
            >
              <Menu size={24} />
            </button>
            <h2 className="text-lg font-bold text-slate-800 capitalize truncate flex items-center gap-2">
              {location.pathname === '/dashboard' && <LayoutDashboard size={20} className="text-indigo-600"/>}
              {location.pathname.replace('/', '') || 'Dashboard'}
            </h2>
          </div>

          <div className="flex items-center space-x-2 md:space-x-4">
             <div className="hidden sm:flex flex-col items-end">
               <span className="text-[10px] text-slate-400 font-bold uppercase">License ID</span>
               <span className="text-xs font-mono font-bold text-slate-700 bg-slate-100 px-2 py-0.5 rounded">{user.gln}</span>
             </div>

             <div className="flex items-center gap-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full border border-emerald-100">
               <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
               </span>
               <span className="hidden md:inline text-xs font-bold uppercase tracking-wide">Mainnet</span>
             </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-6 scroll-smooth">
          {children}
        </main>
      </div>
    </div>
  );
};

export default Layout;

import { GoogleGenAI } from "@google/genai";
import { LedgerService } from "./ledgerService";

// Helper to get the AI instance safely across different build environments
const getAI = () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    console.warn("API_KEY not found in environment variables");
    return null;
  }

  return new GoogleGenAI({ apiKey });
};

export const GeminiService = {
  analyzeLedger: async (userQuery: string): Promise<string> => {
    const ai = getAI();
    if (!ai) return "AI services are currently unavailable. Please check your API key configuration.";

    // Use async export to ensure we get data even if running in remote mode
    const batches = await LedgerService.exportLedger();
    const ledgerData = JSON.stringify(batches, null, 2);

    const systemPrompt = `
      You are an expert Supply Chain Audit AI for the "E-Ledger" blockchain system.
      Your goal is to assist Regulatory Officers, Manufacturers (Excise/Pharma), and Retailers by analyzing the supply chain ledger.

      Here is the current Ledger Data (JSON):
      ${ledgerData}

      Rules:
      1. Answer the user's question based strictly on the provided JSON data.
      2. If asked about "Duty", check the 'dutyPaid' boolean field. Identify illicit/bonded stock.
      3. For Pharma queries, focus on Lot numbers, expiry dates, and chain of custody.
      4. Highlight any "QUARANTINED", "SEIZED", or "RECALLED" batches immediately.
      5. Keep answers professional, concise, and helpful for enforcement or compliance.
      6. Do not invent data not present in the JSON.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            role: 'user',
            parts: [{ text: systemPrompt + "\n\nUser Question: " + userQuery }]
          }
        ]
      });

      return response.text || "I could not generate a response.";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "I encountered an error analyzing the ledger. Please try again later.";
    }
  }
};

import React, { useState, useEffect } from 'react';
import { AuthService } from '../services/authService';
import { User } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { ShieldCheck, Loader2, ArrowRight, Lock, KeyRound, CheckCircle2, Settings, Server, AlertTriangle, Save, Stamp } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const REMEMBER_KEY = 'eledger_remembered_gln';

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [view, setView] = useState<'login' | 'forgot'>('login');

  const [gln, setGln] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const [resetGln, setResetGln] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [resetStep, setResetStep] = useState(1); 

  const [showSettings, setShowSettings] = useState(false);
  const [useRemote, setUseRemote] = useState(false);
  const [apiUrl, setApiUrl] = useState('http://localhost:3001/api');

  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const savedGln = localStorage.getItem(REMEMBER_KEY);
    if (savedGln) {
      setGln(savedGln);
      setRememberMe(true);
    }
    setUseRemote(localStorage.getItem('ELEDGER_USE_REMOTE') === 'true');
    setApiUrl(localStorage.getItem('ELEDGER_API_URL') || 'http://localhost:3001/api');
  }, []);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const user = await AuthService.login(gln, password);
      if (user) {
        if (rememberMe) {
          localStorage.setItem(REMEMBER_KEY, gln);
        } else {
          localStorage.removeItem(REMEMBER_KEY);
        }

        onLogin(user);
        navigate('/dashboard');
      } else {
        if (!useRemote) {
          setError('Invalid License No / GLN or Password.');
        } else {
          setError('Invalid Credentials.');
        }
      }
    } catch (err) {
      setError('Connection failed. Please check network.');
    } finally {
      setLoading(false);
    }
  };

  const handleResetSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Step 1: Verify Identity
    if (resetStep === 1) {
        if (resetGln.length < 5) {
            setError('Invalid License No / GLN format.');
            return;
        }
        setLoading(true);
        try {
            const exists = await AuthService.checkUser(resetGln);
            if (exists) {
                setResetStep(2);
                setSuccess('Identity Verified.');
            } else {
                setError('License No / GLN not found in registry.');
            }
        } catch (err) {
            setError('Verification failed.');
        } finally {
            setLoading(false);
        }
        return;
    }

    // Step 2: Update Password
    setLoading(true);
    try {
      if (newPassword.length < 4) throw new Error("Password too short.");
      if (newPassword !== confirmPassword) throw new Error("Passwords mismatch.");

      const result = await AuthService.resetPassword(resetGln, newPassword);
      if (result) {
        setSuccess('Password reset successfully. Please login.');
        setTimeout(() => {
            setView('login');
            setGln(resetGln);
            setPassword('');
            setResetStep(1);
            setSuccess('');
        }, 2000);
      } else {
        setError('License No / GLN not found.');
      }
    } catch (err: any) {
      setError(err.message || 'Reset failed.');
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = () => {
    localStorage.setItem('ELEDGER_USE_REMOTE', String(useRemote));
    localStorage.setItem('ELEDGER_API_URL', apiUrl);
    window.location.reload(); 
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 overflow-y-auto">

      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-900 p-4 text-white flex justify-between items-center">
               <h3 className="font-bold flex items-center gap-2">
                 <Server size={18} />
                 <span>Network Settings</span>
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-slate-400 hover:text-white">✕</button>
            </div>
            <div className="p-6 space-y-4">
               <div className="flex items-start gap-3 bg-blue-50 p-3 rounded-lg border border-blue-100 text-sm text-blue-800">
                 <AlertTriangle size={18} className="shrink-0 mt-0.5" />
                 <p>
                   <strong>Demo Mode (Local):</strong> Data stored in browser only.<br/><br/>
                   <strong>Mainnet Mode:</strong> Connects to centralized E-Ledger Database.
                 </p>
               </div>

               <div className="space-y-3">
                 <label className="flex items-center gap-3 cursor-pointer p-3 border border-slate-200 rounded-lg hover:bg-slate-50 transition-colors">
                    <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" checked={useRemote} onChange={e => setUseRemote(e.target.checked)} />
                    <span className="font-medium text-slate-700">Use Remote Network Node</span>
                 </label>

                 <div className={`transition-opacity ${useRemote ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Node API Endpoint</label>
                    <input type="text" value={apiUrl} onChange={e => setApiUrl(e.target.value)} className="w-full border border-slate-300 rounded px-3 py-2 text-sm font-mono" />
                 </div>
               </div>

               <button onClick={saveSettings} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg flex justify-center items-center gap-2 mt-4">
                 <Save size={18} />
                 <span>Save Configuration</span>
               </button>
            </div>
          </div>
        </div>
      )}

      {/* Login Card */}
      <div className="max-w-[540px] w-full bg-white rounded-3xl shadow-xl overflow-hidden transition-all duration-300 relative my-auto">
        <button onClick={() => setShowSettings(true)} className="absolute top-4 right-4 z-20 p-2 bg-slate-800/50 hover:bg-slate-800 text-white rounded-full backdrop-blur-sm transition-colors">
          <Settings size={16} />
        </button>

        <div className="bg-slate-900 p-6 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
          <div className="relative z-10">
            <div className="inline-block p-2.5 bg-indigo-600 rounded-2xl mb-2 shadow-lg shadow-indigo-900/50 transform rotate-3">
              {view === 'login' ? <Stamp size={24} className="text-white" /> : <KeyRound size={24} className="text-white" />}
            </div>
            <h1 className="text-2xl font-extrabold text-white mb-0.5 tracking-tight">E-Ledger</h1>
            <p className="text-slate-400 text-xs font-medium">Supply Chain Integrity Portal</p>
          </div>
        </div>

        <div className="p-6">
          {!useRemote && (
            <div className="mb-4 flex flex-col gap-2">
              <div className="flex justify-center">
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide bg-slate-100 text-slate-500 border border-slate-200">
                  <Settings size={10} />
                  Simulation Mode
                </span>
              </div>
            </div>
          )}

          {error && (
            <div className="mb-4 p-2.5 bg-red-50 border border-red-200 text-red-600 text-xs font-medium rounded-lg text-center animate-in fade-in">
              {error}
            </div>
          )}
          {success && (
            <div className="mb-4 p-2.5 bg-green-50 border border-green-200 text-green-700 text-xs font-medium rounded-lg text-center flex items-center justify-center gap-2 animate-in fade-in">
              <CheckCircle2 size={14} />
              {success}
            </div>
          )}

          {view === 'login' ? (
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1">
                  License No / GLN
                </label>
                <input
                  type="text"
                  required
                  value={gln}
                  onChange={(e) => setGln(e.target.value)}
                  className="w-full border border-slate-200 bg-slate-50 rounded-xl px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition font-mono text-sm text-slate-900"
                  placeholder="0000000000000"
                />
              </div>
              <div>
                <div className="flex justify-between items-center mb-1">
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider">Password</label>
                  <button type="button" onClick={() => { setView('forgot'); setError(''); }} className="text-[10px] text-indigo-600 hover:text-indigo-800 font-bold">Forgot?</button>
                </div>
                <input 
                  type="password" 
                  required 
                  value={password} 
                  onChange={(e) => setPassword(e.target.value)} 
                  className="w-full border border-slate-200 bg-slate-50 rounded-xl px-3 py-2 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition text-sm text-slate-900" 
                  placeholder="••••••••" 
                />
              </div>

              <div className="flex items-center">
                <input id="remember-me" type="checkbox" checked={rememberMe} onChange={(e) => setRememberMe(e.target.checked)} className="h-3.5 w-3.5 text-indigo-600 rounded cursor-pointer" />
                <label htmlFor="remember-me" className="ml-2 block text-xs text-slate-600 cursor-pointer select-none">Remember GLN</label>
              </div>

              <button 
                type="submit" 
                disabled={loading} 
                className="w-full bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-500/40 hover:scale-[1.02] active:scale-[0.98] disabled:opacity-70 text-white font-bold py-2.5 rounded-xl shadow-lg shadow-indigo-200 transition-all duration-300 ease-in-out flex items-center justify-center space-x-2 text-sm"
              >
                {loading ? <Loader2 size={18} className="animate-spin" /> : <><span>Secure Login</span><ArrowRight size={16} /></>}
              </button>
            </form>
          ) : (
            <form onSubmit={handleResetSubmit} className="space-y-4">
              {resetStep === 1 && (
                <>
                  <p className="text-xs text-slate-600 text-center mb-2 leading-relaxed">Enter your License Number to verify identity.</p>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1">License / GLN</label>
                    <input type="text" autoFocus required value={resetGln} onChange={(e) => setResetGln(e.target.value)} className="w-full border border-slate-200 bg-slate-50 rounded-xl px-3 py-2 focus:ring-2 focus:ring-indigo-500 font-mono text-sm text-slate-900" />
                  </div>
                  <button type="submit" disabled={loading} className="w-full bg-slate-800 hover:bg-slate-700 text-white font-bold py-2.5 rounded-xl transition-colors shadow-lg text-sm flex items-center justify-center gap-2">
                    {loading ? <Loader2 size={16} className="animate-spin" /> : 'Verify Identity'}
                  </button>
                </>
              )}

              {resetStep === 2 && (
                <>
                   <p className="text-xs text-slate-600 text-center mb-2">Identity verified. Set new password.</p>
                   <div>
                     <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1">New Password</label>
                     <input type="password" required value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full border border-slate-200 bg-slate-50 rounded-xl px-3 py-2 focus:ring-2 focus:ring-indigo-500 text-sm text-slate-900" />
                   </div>
                   <div>
                     <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1">Confirm</label>
                     <input type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} className={`w-full border bg-slate-50 rounded-xl px-3 py-2 focus:ring-2 outline-none text-sm text-slate-900 ${confirmPassword && confirmPassword !== newPassword ? 'border-red-400 focus:ring-red-400' : 'border-slate-200 focus:ring-indigo-500'}`} />
                   </div>
                  <button type="submit" disabled={loading} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2.5 rounded-xl transition-colors flex justify-center items-center gap-2 shadow-lg text-sm">{loading ? <Loader2 size={18} className="animate-spin"/> : <Lock size={16} />}<span>Update Password</span></button>
                </>
              )}
              <button type="button" onClick={() => { setView('login'); setError(''); setResetStep(1); }} className="w-full mt-2 text-slate-500 hover:text-slate-800 text-xs font-medium py-2">Back to Login</button>
            </form>
          )}

          {view === 'login' && (
            <div className="mt-4 pt-4 border-t border-slate-100 text-center">
              <p className="text-slate-400 text-xs mb-1">New Trading Partner?</p>
              <Link to="/signup" className="text-indigo-600 hover:text-indigo-800 font-bold text-xs transition-colors uppercase tracking-wide">Register Account</Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AuthService } from '../services/authService';
import { UserRole } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { ShieldCheck, Loader2, Building2, UserCircle, MapPin, RefreshCw, AlertTriangle, ArrowRight } from 'lucide-react';

const Signup: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    orgName: '',
    gln: '',
    role: UserRole.MANUFACTURER,
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isRemote, setIsRemote] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    setIsRemote(localStorage.getItem('ELEDGER_USE_REMOTE') === 'true');
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleGenerateGLN = (e: React.MouseEvent) => {
    e.preventDefault();
    const newGln = AuthService.generateGLN();
    setFormData(prev => ({ ...prev, gln: newGln }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (formData.gln.length !== 13) {
        throw new Error('GLN must be exactly 13 digits.');
      }

      await AuthService.signup(
        formData.name,
        formData.orgName,
        formData.gln,
        formData.role,
        formData.password
      );
      navigate('/login');
    } catch (err: any) {
      setError(err.message || 'Failed to register.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[600px]">

        {/* Sidebar */}
        <div className="hidden md:flex w-5/12 bg-slate-900 p-10 text-white flex-col justify-between relative overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

          <div className="relative z-10">
            <div className="inline-block p-3 bg-indigo-600 rounded-2xl mb-6 shadow-lg shadow-indigo-900/40">
              <ShieldCheck size={32} />
            </div>
            <h2 className="text-3xl font-extrabold mb-3 tracking-tight">E-Ledger Registry</h2>
            <p className="text-slate-400 text-sm leading-relaxed">
              Register your Manufacturer, Hub, or Retail node on the global GS1 blockchain network.
            </p>
          </div>

          <div className="relative z-10 space-y-6">
             <div className="flex items-center gap-4 text-sm text-slate-300">
               <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center font-bold">1</div>
               <p>Identity Verification</p>
             </div>
             <div className="flex items-center gap-4 text-sm text-slate-300">
               <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center font-bold">2</div>
               <p>License Mapping</p>
             </div>
             <div className="flex items-center gap-4 text-sm text-slate-300">
               <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center font-bold">3</div>
               <p>Ledger Access</p>
             </div>
          </div>

          <div className="text-[10px] text-slate-500 font-mono relative z-10">
            SECURE SUPPLY CHAIN GATEWAY © 2024
          </div>
        </div>

        {/* Form Area */}
        <div className="flex-1 p-8 md:p-12 flex flex-col justify-center">
          <div className="flex justify-between items-start mb-8">
             <div>
                <h2 className="text-2xl font-bold text-slate-800">Node Registration</h2>
                <p className="text-slate-500 text-sm mt-1">Onboard your business entity</p>
             </div>
             <Link to="/login" className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full hover:bg-indigo-100 transition-colors">
               LOGIN INSTEAD
             </Link>
          </div>

          {!isRemote && (
            <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-xl flex gap-3">
              <AlertTriangle className="text-amber-600 shrink-0 mt-0.5" size={20} />
              <div className="text-xs text-amber-800 leading-relaxed">
                <strong className="block mb-1 font-bold">Simulation Mode Active</strong>
                Account data will be stored locally in your browser.
              </div>
            </div>
          )}

          {error && <div className="mb-6 p-3 bg-red-50 border border-red-200 text-red-600 text-sm rounded-xl font-medium">{error}</div>}

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Primary Contact</label>
                <div className="relative">
                  <UserCircle size={18} className="absolute left-3 top-3 text-slate-400" />
                  <input name="name" required value={formData.name} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="Full Name" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Business Name</label>
                <div className="relative">
                  <Building2 size={18} className="absolute left-3 top-3 text-slate-400" />
                  <input name="orgName" required value={formData.orgName} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="e.g. PharmaCorp Int" />
                </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Global Location Number (GLN)</label>
              <div className="flex space-x-2">
                <div className="relative flex-1">
                  <MapPin size={18} className="absolute left-3 top-3 text-slate-400" />
                  <input name="gln" required maxLength={13} minLength={13} value={formData.gln} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono" placeholder="0000000000000" />
                </div>
                <button type="button" onClick={handleGenerateGLN} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl border border-slate-200 transition-colors font-medium text-xs flex items-center gap-1" title="Generate Random">
                   <RefreshCw size={14} /> <span>Gen</span>
                </button>
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Business Category</label>
              <select name="role" value={formData.role} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-white cursor-pointer">
                <option value={UserRole.MANUFACTURER}>Manufacturer / Bottling Plant</option>
                <option value={UserRole.DISTRIBUTOR}>Warehouse / Logistics Hub</option>
                <option value={UserRole.RETAILER}>Retail / Pharmacy / Point of Consumption</option>
                <option value={UserRole.REGULATOR}>Regulatory Authority (Govt)</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Access Key (Password)</label>
              <input name="password" type="password" required value={formData.password} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm" placeholder="••••••••" />
            </div>

            <button type="submit" disabled={loading} className="w-full mt-6 bg-slate-900 hover:bg-slate-800 disabled:opacity-70 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 transform hover:translate-y-[-1px]">
              {loading ? <Loader2 size={20} className="animate-spin" /> : <><span>Complete Registration</span><ArrowRight size={18} /></>}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Signup;

import React, { useState } from 'react';
import { LedgerService } from '../services/ledgerService';
import { Batch } from '../types';
import { Search, ShieldCheck, XCircle, Clock, MapPin, CheckCircle2, Fingerprint, Camera, Stamp, AlertOctagon, Award } from 'lucide-react';
import QRScanner from './QRScanner';

const ProductVerifier: React.FC = () => {
  const [query, setQuery] = useState('');
  const [result, setResult] = useState<Batch | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [duplicateAlert, setDuplicateAlert] = useState<{detected: boolean, msg: string}>({ detected: false, msg: '' });

  const handleVerify = async (e?: React.FormEvent, directInput?: string) => {
    if (e) e.preventDefault();
    const searchQuery = directInput || query;
    if (!searchQuery.trim()) return;

    setLoading(true);
    setError('');
    setResult(null);
    setSearched(true);
    setDuplicateAlert({ detected: false, msg: '' });

    try {
      // 1. Anti-Counterfeit Check (POS API)
      const posCheck = await LedgerService.checkPOSStatus(searchQuery.trim(), 'public_verifier');

      if (posCheck.status === 'DUPLICATE') {
         setDuplicateAlert({ detected: true, msg: posCheck.message });
         setLoading(false);
         return; 
      }

      // 2. Data Lookup
      let batch = await LedgerService.verifyByHash(searchQuery.trim());
      if (!batch) {
        batch = await LedgerService.getBatchByID(searchQuery.trim());
      }

      if (batch) {
        setResult(batch);
        setQuery(searchQuery.trim());
      } else {
        setError('Invalid Identification. This product may be illicit or counterfeit.');
      }
    } catch (err) {
      setError('Verification Error.');
    } finally {
      setLoading(false);
    }
  };

  const handleCameraScan = (text: string) => {
    setShowScanner(false);
    setQuery(text);
    handleVerify(undefined, text);
  };

  return (
    <div className="w-full">
      {showScanner && (
        <QRScanner 
          onScan={handleCameraScan} 
          onClose={() => setShowScanner(false)} 
        />
      )}

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Authenticity Verification</h2>
           <p className="text-slate-500 text-sm">Official E-Ledger Integrity Portal</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 mb-8 w-full overflow-hidden">
        <form onSubmit={e => handleVerify(e)} className="p-4 md:p-6 flex flex-col md:flex-row items-center gap-3 md:gap-4 bg-slate-50 border-b border-slate-100">
          <div className="relative flex-1 w-full max-w-2xl">
            <Search className="absolute left-4 top-3.5 text-slate-400" size={20} />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Enter Product Hash or Batch ID..."
              className="w-full pl-12 pr-12 py-3.5 rounded-xl border border-slate-300 focus:ring-2 focus:ring-indigo-500 outline-none transition font-mono text-sm shadow-sm"
            />
            <button
               type="button"
               onClick={() => setShowScanner(true)}
               className="absolute right-3 top-2.5 p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
               title="Scan"
            >
               <Camera size={22} />
            </button>
          </div>
          <button 
            type="submit" 
            disabled={loading || !query}
            className="w-full md:w-auto px-8 py-3.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-bold rounded-xl transition-all shadow-md active:scale-95 whitespace-nowrap"
          >
            {loading ? 'Verifying...' : 'Check Authenticity'}
          </button>
        </form>

        {/* Counterfeit / Duplicate Alert */}
        {duplicateAlert.detected && (
          <div className="bg-red-50 border-l-8 border-red-600 p-6 m-4 md:m-8 rounded-r-xl shadow-inner animate-in fade-in slide-in-from-top-2">
            <div className="flex items-start gap-5">
              <div className="bg-red-100 p-3 rounded-full shrink-0">
                <AlertOctagon size={40} className="text-red-600" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-red-700 uppercase tracking-wide">Counterfeit Alert</h3>
                <p className="text-lg font-bold text-red-900 mt-1">{duplicateAlert.msg}</p>
                <p className="text-sm text-red-800 mt-2 leading-relaxed">
                  This specific identifier has already been marked as <strong>SOLD</strong> or <strong>CONSUMED</strong>. 
                  Multiple scans of the same ID indicate a cloned label or refilled container.
                </p>
                <div className="mt-4 inline-block bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-sm shadow-md">
                  ⛔ STOP: DO NOT PURCHASE / USE
                </div>
              </div>
            </div>
          </div>
        )}

        {searched && !loading && !result && !error && !duplicateAlert.detected && (
           <div className="p-16 text-center text-slate-400">
              <Search size={48} className="mx-auto mb-4 opacity-20" />
              <p>No records found on the global ledger. Please check the ID.</p>
           </div>
        )}

        {error && (
          <div className="p-12 text-center bg-red-50 m-4 rounded-xl border border-red-100">
            <XCircle size={56} className="text-red-500 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-red-700">Verification Failed</h3>
            <p className="text-red-600 mt-2 max-w-md mx-auto">{error}</p>
          </div>
        )}

        {result && (
          <div className="bg-white animate-in fade-in slide-in-from-bottom-8 duration-700">

            {/* Certificate Header */}
            <div className={`relative overflow-hidden p-8 text-white ${result.dutyPaid ? 'bg-emerald-600' : 'bg-amber-500'}`}>
                <div className="absolute inset-0 opacity-10 pointer-events-none" style={{
                    backgroundImage: 'radial-gradient(circle, #fff 2px, transparent 2.5px)',
                    backgroundSize: '20px 20px'
                }}></div>

                <div className="relative z-10 flex items-start justify-between">
                    <div>
                        <div className="flex items-center space-x-2 font-black opacity-90 uppercase tracking-widest text-xs mb-2">
                            <ShieldCheck size={16} />
                            <span>Verified Integrity Document</span>
                        </div>
                        <h3 className="text-3xl font-bold tracking-tight">{result.productName}</h3>
                        <p className="text-white/80 font-mono mt-1 text-sm">{result.batchID}</p>
                    </div>
                    <div className="hidden sm:flex flex-col items-end">
                        <Award size={48} className="text-white/30 mb-2" />
                        <span className="text-2xl font-black uppercase tracking-widest">{result.dutyPaid ? 'COMPLIANT' : 'BONDED'}</span>
                    </div>
                </div>
            </div>

            <div className="p-6 md:p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <h4 className="font-bold text-slate-800 uppercase tracking-wider text-xs border-b border-slate-100 pb-2 flex items-center gap-2">
                    <Fingerprint size={16} className="text-indigo-500" />
                    Product DNA (GS1)
                </h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Potency / Strength</p>
                    <p className="font-bold text-lg text-slate-800">{result.alcoholContent || 'N/A'}<span className="text-xs text-slate-500 ml-1">Unit</span></p>
                  </div>
                  <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Volume / Qty</p>
                    <p className="font-bold text-lg text-slate-800">{result.quantity} <span className="text-xs text-slate-500">{result.unit}</span></p>
                  </div>
                  <div className="p-4 bg-slate-50 rounded-xl border border-slate-100 col-span-2">
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">Expiry / Manufacture</p>
                    <p className="font-bold text-lg text-slate-800">{result.expiryDate}</p>
                  </div>
                </div>

                {result.integrityHash && (
                  <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-xl">
                    <div className="flex items-center space-x-2 text-indigo-700 mb-2">
                      <Fingerprint size={18} />
                      <span className="font-bold text-sm">Blockchain Integrity Seal</span>
                    </div>
                    <p className="font-mono text-[10px] break-all bg-white p-2 rounded border border-indigo-200 text-slate-500 shadow-inner">
                      {result.integrityHash}
                    </p>
                  </div>
                )}
              </div>

              <div>
                <h4 className="font-bold text-slate-800 uppercase tracking-wider text-xs border-b border-slate-100 pb-2 mb-4 flex items-center gap-2">
                    <MapPin size={16} className="text-indigo-500" />
                    Immutable Chain of Custody
                </h4>
                <div className="space-y-6 relative pl-6 border-l-2 border-slate-200 ml-2">
                  {result.trace.sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()).map((event, idx) => (
                    <div key={idx} className="relative group">
                       <div className={`absolute -left-[31px] w-4 h-4 rounded-full border-2 border-white shadow-sm transition-transform group-hover:scale-125 ${idx === 0 ? 'bg-indigo-500' : 'bg-slate-300'}`}></div>
                       <div>
                         <div className="flex justify-between items-center">
                            <p className="font-bold text-sm text-slate-800">{event.type}</p>
                            <span className="text-[10px] font-mono text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded">{new Date(event.timestamp).toLocaleDateString()}</span>
                         </div>
                         <div className="mt-1.5 bg-slate-50 p-2.5 rounded-lg border border-slate-100 text-xs shadow-sm">
                           <p className="font-semibold text-slate-700">{event.actorName}</p>
                           <p className="text-slate-500 flex items-center gap-1 mt-0.5">
                             <MapPin size={10} />
                             {event.location}
                           </p>
                         </div>
                       </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-slate-50 p-4 border-t border-slate-100 text-center">
                <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">Verified via E-Ledger Distributed Network</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductVerifier;

import React, { useState, useRef, useEffect } from 'react';
import { GeminiService } from '../services/geminiService';
import { Bot, Send, User as UserIcon, Loader2 } from 'lucide-react';

interface Message {
  id: string;
  sender: 'user' | 'ai';
  text: string;
  timestamp: Date;
}

const Assistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      sender: 'ai',
      text: "Hello! I'm your E-Ledger AI Analyst. I have real-time access to the current supply chain state. Ask me about inventory risks, compliance status, or batch tracing.",
      timestamp: new Date()
    }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      sender: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const responseText = await GeminiService.analyzeLedger(userMsg.text);

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      sender: 'ai',
      text: responseText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, aiMsg]);
    setIsTyping(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-8rem)] w-full bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex items-center space-x-3 shrink-0">
        <div className="bg-gradient-to-br from-indigo-500 to-purple-600 p-2 rounded-lg">
          <Bot size={24} className="text-white" />
        </div>
        <div>
          <h2 className="font-bold text-slate-800">E-Ledger Analyst</h2>
          <p className="text-xs text-slate-500 flex items-center gap-1">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            Blockchain Intelligence Node
          </p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
        {messages.map(msg => (
          <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] md:max-w-[70%] rounded-2xl px-5 py-3 shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-blue-600 text-white rounded-br-none' 
                : 'bg-white text-slate-700 border border-slate-200 rounded-bl-none'
            }`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
              <p className={`text-[10px] mt-1 opacity-70 ${msg.sender === 'user' ? 'text-blue-100' : 'text-slate-400'}`}>
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
             <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-5 py-4 shadow-sm flex items-center space-x-2">
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-150"></div>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSend} className="p-4 bg-white border-t border-slate-200 flex items-center space-x-3 shrink-0">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Analyze batch risks, inventory efficiency, or compliance..."
          className="flex-1 border border-slate-300 rounded-full px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition"
        />
        <button 
          type="submit" 
          disabled={!input.trim() || isTyping}
          className="bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white p-3 rounded-full shadow-md transition-colors"
        >
          {isTyping ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />}
        </button>
      </form>
    </div>
  );
};

export default Assistant;

export enum Sector {
  EXCISE = 'EXCISE',
  PHARMA = 'PHARMA'
}

export enum UserRole {
  MANUFACTURER = 'MANUFACTURER',
  DISTRIBUTOR = 'DISTRIBUTOR',
  RETAILER = 'RETAILER',
  REGULATOR = 'REGULATOR',
  AUDITOR = 'AUDITOR'
}

export enum BatchStatus {
  CREATED = 'CREATED',
