const Signup: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    orgName: '',
    gln: '',
    country: 'IN',
    sector: Sector.EXCISE,
    role: UserRole.MANUFACTURER,
    positionLabel: 'Distillery / Brewery / Bottler',
    password: ''
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);
  const navigate = useNavigate();

  const selectedCountry = useMemo(() => 
    REGISTRY_CONFIG.find(c => c.code === formData.country), 
  [formData.country]);

  const availablePositions = useMemo(() => {
    if (!selectedCountry) return [];
    return selectedCountry.sectors[formData.sector].roles;
  }, [selectedCountry, formData.sector]);

  // Sync position label when sector or country changes
  useEffect(() => {
    if (availablePositions.length > 0) {
      setFormData(prev => ({
        ...prev,
        role: availablePositions[0].role,
        positionLabel: availablePositions[0].label
      }));
    }
  }, [availablePositions]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name === 'position') {
      const pos = availablePositions.find(p => p.label === value);
      if (pos) {
        setFormData(prev => ({ ...prev, role: pos.role, positionLabel: pos.label }));
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleGenerateGLN = (e: React.MouseEvent) => {
    e.preventDefault();
    const newGln = AuthService.generateGLN();
    setFormData(prev => ({ ...prev, gln: newGln }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (formData.gln.length !== 13) {
        throw new Error('GLN must be exactly 13 digits.');
      }

      await AuthService.signup(
        formData.name,
        formData.orgName,
        formData.gln,
        formData.role,
        formData.password,
        {
          country: formData.country,
          sector: formData.sector,
          positionLabel: formData.positionLabel
        }
      );
      navigate('/login');
    } catch (err: any) {
      setError(err.message || 'Failed to register.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[650px]">

        {/* Sidebar Info */}
        <div className="hidden md:flex w-5/12 bg-slate-900 p-10 text-white flex-col justify-between relative overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

          <div className="relative z-10">
            <div className="inline-block p-3 bg-indigo-600 rounded-2xl mb-6 shadow-lg shadow-indigo-900/40">
              <ShieldCheck size={32} />
            </div>
            <h2 className="text-3xl font-extrabold mb-3 tracking-tight leading-tight">Join the Global Ledger</h2>
            <p className="text-slate-400 text-sm leading-relaxed">
              Standardized GS1 nodes for global {formData.sector === Sector.EXCISE ? 'Excise' : 'Pharmaceutical'} compliance across {selectedCountry?.name}.
            </p>
          </div>

          <div className="relative z-10 space-y-4">
             {[1, 2, 3].map(s => (
                <div key={s} className={`flex items-center gap-4 text-sm transition-all duration-300 ${step === s ? 'text-white scale-105' : 'text-slate-500'}`}>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold border ${step === s ? 'bg-indigo-600 border-indigo-600' : 'bg-slate-800 border-slate-700'}`}>{s}</div>
                  <p>{s === 1 ? 'Market Selection' : s === 2 ? 'Identity Mapping' : 'Secure Access'}</p>
                </div>
             ))}
          </div>

          <div className="text-[10px] text-slate-500 font-mono relative z-10">
            E-LEDGER NETWORK v3.5 • GS1 EPCIS COMPLIANT
          </div>
        </div>

        {/* Form Area */}
        <div className="flex-1 p-8 md:p-12 flex flex-col justify-center">
          <div className="flex justify-between items-start mb-8">
             <div>
                <h2 className="text-2xl font-bold text-slate-800">Node Onboarding</h2>
                <p className="text-slate-500 text-sm mt-1">Step {step} of 3</p>
             </div>
             <Link to="/login" className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full hover:bg-indigo-100 transition-colors">
               LOGIN
