          </div>

          {error && <div className="mb-6 p-3 bg-red-50 border border-red-200 text-red-600 text-sm rounded-xl font-medium">{error}</div>}

          <form onSubmit={handleSubmit} className="space-y-5">
            {step === 1 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Operating Country</label>
                  <div className="relative">
                    <Globe size={18} className="absolute left-3 top-3 text-slate-400" />
                    <select name="country" value={formData.country} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-white cursor-pointer appearance-none">
                      {REGISTRY_CONFIG.map(c => <option key={c.code} value={c.code}>{c.name}</option>)}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Primary Industry Sector</label>
                  <div className="flex gap-2">
                    {[Sector.EXCISE, Sector.PHARMA].map(s => (
                      <button 
                        key={s} type="button" 
                        onClick={() => setFormData(prev => ({...prev, sector: s}))}
                        className={`flex-1 py-3 rounded-xl border font-bold text-xs flex flex-col items-center gap-1 transition-all ${formData.sector === s ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'}`}
                      >
                        <Layers size={16} />
                        {s}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Stakeholder Position</label>
                  <select name="position" value={formData.positionLabel} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-white cursor-pointer">
                    {availablePositions.map(p => (
                      <option key={p.label} value={p.label}>{p.label}</option>
                    ))}
                  </select>
                  <p className="text-[10px] text-slate-400 mt-2 px-1">
                    {availablePositions.find(p => p.label === formData.positionLabel)?.description}
                  </p>
                </div>

                <button type="button" onClick={() => setStep(2)} className="w-full mt-4 bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">
                  <span>Continue</span>
                  <ArrowRight size={18} />
                </button>
              </div>
            )}

            {step === 2 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Primary Contact</label>
                    <div className="relative">
                      <UserCircle size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="name" required value={formData.name} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="Full Name" />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Organization Name</label>
                    <div className="relative">
                      <Building2 size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="orgName" required value={formData.orgName} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="e.g. PharmaCorp Int" />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Global Location Number (GLN)</label>
                  <div className="flex space-x-2">
                    <div className="relative flex-1">
                      <MapPin size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="gln" required maxLength={13} minLength={13} value={formData.gln} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono" placeholder="13 digits" />
                    </div>
                    <button type="button" onClick={handleGenerateGLN} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl border border-slate-200 transition-colors font-medium text-xs flex items-center gap-1" title="Generate Random">
                      <RefreshCw size={14} /> <span>Gen</span>
                    </button>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button type="button" onClick={() => setStep(1)} className="flex-1 py-3.5 border border-slate-200 rounded-xl text-slate-600 font-bold text-sm">Back</button>
                  <button type="button" onClick={() => setStep(3)} className="flex-[2] bg-slate-900 text-white font-bold py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2">
                    <span>Final Step</span>
                    <ArrowRight size={18} />
                  </button>
                </div>
              </div>
            )}

            {step === 3 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Node Access Password</label>
                  <input name="password" type="password" required value={formData.password} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm" placeholder="••••••••" />
                </div>

                <div className="p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                  <h4 className="text-xs font-bold text-indigo-900 uppercase mb-2 flex items-center gap-2">
                    <ShieldCheck size={14} /> Confirmation
                  </h4>
                  <div className="space-y-1 text-[11px] text-indigo-700 font-medium">
                    <p>Market: {selectedCountry?.name}</p>
                    <p>Sector: {formData.sector}</p>
                    <p>Role: {formData.positionLabel}</p>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button type="button" onClick={() => setStep(2)} className="flex-1 py-3.5 border border-slate-200 rounded-xl text-slate-600 font-bold text-sm">Back</button>
                  <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 hover:bg-indigo-700 disabled:opacity-70 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">
                    {loading ? <Loader2 size={20} className="animate-spin" /> : <><span>Onboard to Mainnet</span><ShieldCheck size={18} /></>}
                  </button>
                </div>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

