import React, { useState, useEffect, useMemo } from 'react';
import { AuthService } from '../services/authService';
import { UserRole, Sector } from '../types';
import { REGISTRY_CONFIG } from '../constants';
import { Link, useNavigate } from 'react-router-dom';
import { ShieldCheck, Loader2, Building2, UserCircle, MapPin, RefreshCw, AlertTriangle, ArrowRight, Globe, Layers, ShoppingBag, Leaf, Pill, Stamp } from 'lucide-react';

const Signup: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    orgName: '',
    gln: '',
    country: 'IN',
    sector: Sector.EXCISE,
    role: UserRole.MANUFACTURER,
    positionLabel: 'Distillery / Brewery / Bottler',
    password: ''
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);
  const navigate = useNavigate();

  const selectedCountry = useMemo(() => 
    REGISTRY_CONFIG.find(c => c.code === formData.country), 
  [formData.country]);

  const availablePositions = useMemo(() => {
    if (!selectedCountry) return [];
    return selectedCountry.sectors[formData.sector]?.roles || [];
  }, [selectedCountry, formData.sector]);

  // Sync position label when sector or country changes
  useEffect(() => {
    if (availablePositions.length > 0) {
      setFormData(prev => ({
        ...prev,
        role: availablePositions[0].role,
        positionLabel: availablePositions[0].label
      }));
    }
  }, [availablePositions]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name === 'position') {
      const pos = availablePositions.find(p => p.label === value);
      if (pos) {
        setFormData(prev => ({ ...prev, role: pos.role, positionLabel: pos.label }));
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleGenerateGLN = (e: React.MouseEvent) => {
    e.preventDefault();
    const newGln = AuthService.generateGLN();
    setFormData(prev => ({ ...prev, gln: newGln }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (formData.gln.length !== 13) {
        throw new Error('GLN must be exactly 13 digits.');
      }

      await AuthService.signup(
        formData.name,
        formData.orgName,
        formData.gln,
        formData.role,
        formData.password,
        {
          country: formData.country,
          sector: formData.sector,
          positionLabel: formData.positionLabel
        }
      );
      navigate('/login');
    } catch (err: any) {
      setError(err.message || 'Failed to register.');
    } finally {
      setLoading(false);
    }
  };

  const getSectorIcon = (s: Sector) => {
    switch(s) {
      case Sector.EXCISE: return <Stamp size={18} />;
      case Sector.PHARMA: return <Pill size={18} />;
      case Sector.FMCG: return <ShoppingBag size={18} />;
      case Sector.AGRICULTURE: return <Leaf size={18} />;
      default: return <Layers size={18} />;
    }
  };

  const getSectorColor = (s: Sector) => {
    switch(s) {
      case Sector.EXCISE: return 'bg-indigo-600 border-indigo-600';
      case Sector.PHARMA: return 'bg-emerald-600 border-emerald-600';
      case Sector.FMCG: return 'bg-amber-600 border-amber-600';
      case Sector.AGRICULTURE: return 'bg-green-700 border-green-700';
      default: return 'bg-slate-900 border-slate-900';
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[650px]">

        {/* Sidebar Info */}
        <div className="hidden md:flex w-5/12 bg-slate-900 p-10 text-white flex-col justify-between relative overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

          <div className="relative z-10">
            <div className={`inline-block p-3 rounded-2xl mb-6 shadow-lg shadow-black/40 ${getSectorColor(formData.sector)}`}>
              <ShieldCheck size={32} />
            </div>
            <h2 className="text-3xl font-extrabold mb-3 tracking-tight leading-tight">Global Onboarding</h2>
            <p className="text-slate-400 text-sm leading-relaxed">
              Provisioning GS1 nodes for global {formData.sector.toLowerCase()} transparency across {selectedCountry?.name}.
            </p>
          </div>

          <div className="relative z-10 space-y-4">
             {[1, 2, 3].map(s => (
                <div key={s} className={`flex items-center gap-4 text-sm transition-all duration-300 ${step === s ? 'text-white scale-105' : 'text-slate-500'}`}>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold border ${step === s ? 'bg-indigo-600 border-indigo-600' : 'bg-slate-800 border-slate-700'}`}>{s}</div>
                  <p>{s === 1 ? 'Market Selection' : s === 2 ? 'Identity Mapping' : 'Secure Access'}</p>
                </div>
             ))}
          </div>

          <div className="text-[10px] text-slate-500 font-mono relative z-10">
            E-LEDGER CORE • EPCIS 2.0 COMPLIANT
          </div>
        </div>

        {/* Form Area */}
        <div className="flex-1 p-8 md:p-12 flex flex-col justify-center">
          <div className="flex justify-between items-start mb-8">
             <div>
                <h2 className="text-2xl font-bold text-slate-800">Identity Portal</h2>
                <p className="text-slate-500 text-sm mt-1">Step {step} of 3</p>
             </div>
             <Link to="/login" className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-full hover:bg-indigo-100 transition-colors">
               SIGN IN
             </Link>
          </div>

          {error && <div className="mb-6 p-3 bg-red-50 border border-red-200 text-red-600 text-sm rounded-xl font-medium">{error}</div>}

          <form onSubmit={handleSubmit} className="space-y-5">
            {step === 1 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Country of Operation</label>
                  <div className="relative">
                    <Globe size={18} className="absolute left-3 top-3 text-slate-400" />
                    <select name="country" value={formData.country} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-white cursor-pointer appearance-none">
                      {REGISTRY_CONFIG.map(c => <option key={c.code} value={c.code}>{c.name}</option>)}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Industry Sector</label>
                  <div className="grid grid-cols-2 gap-2">
                    {[Sector.EXCISE, Sector.PHARMA, Sector.FMCG, Sector.AGRICULTURE].map(s => (
                      <button 
                        key={s} type="button" 
                        onClick={() => setFormData(prev => ({...prev, sector: s}))}
                        className={`py-3 rounded-xl border font-bold text-[10px] flex flex-col items-center gap-1 transition-all ${formData.sector === s ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'}`}
                      >
                        {getSectorIcon(s)}
                        {s}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Stakeholder Position</label>
                  <select name="position" value={formData.positionLabel} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-white cursor-pointer">
                    {availablePositions.map(p => (
                      <option key={p.label} value={p.label}>{p.label}</option>
                    ))}
                  </select>
                  {availablePositions.length > 0 && (
                    <p className="text-[10px] text-slate-400 mt-2 px-1">
                      {availablePositions.find(p => p.label === formData.positionLabel)?.description}
                    </p>
                  )}
                </div>

                <button type="button" onClick={() => setStep(2)} className="w-full mt-4 bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">
                  <span>Continue</span>
                  <ArrowRight size={18} />
                </button>
              </div>
            )}

            {step === 2 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Primary Contact</label>
                    <div className="relative">
                      <UserCircle size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="name" required value={formData.name} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="Full Name" />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Organization</label>
                    <div className="relative">
                      <Building2 size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="orgName" required value={formData.orgName} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all" placeholder="Legal Entity Name" />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">License ID / GLN</label>
                  <div className="flex space-x-2">
                    <div className="relative flex-1">
                      <MapPin size={18} className="absolute left-3 top-3 text-slate-400" />
                      <input name="gln" required maxLength={13} minLength={13} value={formData.gln} onChange={handleChange} className="w-full pl-10 pr-3 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono" placeholder="13 digits" />
                    </div>
                    <button type="button" onClick={handleGenerateGLN} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl border border-slate-200 transition-colors font-medium text-xs flex items-center gap-1">
                      <RefreshCw size={14} /> <span>Gen</span>
                    </button>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button type="button" onClick={() => setStep(1)} className="flex-1 py-3.5 border border-slate-200 rounded-xl text-slate-600 font-bold text-sm">Back</button>
                  <button type="button" onClick={() => setStep(3)} className="flex-[2] bg-slate-900 text-white font-bold py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2">
                    <span>Final Step</span>
                    <ArrowRight size={18} />
                  </button>
                </div>
              </div>
            )}

            {step === 3 && (
              <div className="space-y-5 animate-in fade-in slide-in-from-right-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Node Access Key</label>
                  <input name="password" type="password" required value={formData.password} onChange={handleChange} className="w-full px-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm" placeholder="••••••••" />
                </div>

                <div className="p-4 bg-slate-50 rounded-xl border border-slate-200">
                  <h4 className="text-xs font-bold text-slate-900 uppercase mb-2 flex items-center gap-2">
                    <ShieldCheck size={14} className="text-emerald-600" /> Review Application
                  </h4>
                  <div className="grid grid-cols-2 gap-y-2 text-[10px] text-slate-600 font-medium">
                    <p className="text-slate-400 uppercase">Country</p><p>{selectedCountry?.name}</p>
                    <p className="text-slate-400 uppercase">Sector</p><p className="font-bold text-slate-800">{formData.sector}</p>
                    <p className="text-slate-400 uppercase">Stakeholder</p><p>{formData.positionLabel}</p>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button type="button" onClick={() => setStep(2)} className="flex-1 py-3.5 border border-slate-200 rounded-xl text-slate-600 font-bold text-sm">Back</button>
                  <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 hover:bg-indigo-700 disabled:opacity-70 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">
                    {loading ? <Loader2 size={20} className="animate-spin" /> : <><span>Complete Onboarding</span><ShieldCheck size={18} /></>}
                  </button>
                </div>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

