      fetchData(); 
      setFormData({ 
        gtin: '', productName: '', lotNumber: '', expiryDate: '', quantity: 0, unit: 'Cases', alcoholContent: 42.8, category: 'IMFL', isDutyPaid: false, hsnCode: '2208', taxableValue: 0, taxRate: 18 
      });
